#include <stddef.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    const char *abbr;
    int          layer;
} term_entry_t;

static const term_entry_t TERM_TABLE[] = {
    { "MCU",    2 },
    { "LDO",    2 },
    { "DMA",    3 },
    { "HAL",    3 },
    { "RTOS",   4 },
    { "ROOTFS", 5 },
    { "OTA",    6 },
    { "JTAG",   7 },
    { "SWD",    7 },
    { "BSP",    8 },
    { "TINYML", 9 }
};

int layer_of_term(const char *abbr)
{
    char buf[16];
    size_t i;
    size_t n = 0;

    if (abbr == NULL) {
        return -1;
    }

    /* 归一化：跳过首部空白，取到下一个空白为止的词元，并统一转为大写 */
    while (*abbr != '\0' && isspace((unsigned char)*abbr) != 0) {
        ++abbr;
    }
    while (*abbr != '\0' && isspace((unsigned char)*abbr) == 0) {
        if (n + 1 >= sizeof(buf)) {
            return 0;               /* 超长输入必然不在表中 */
        }
        buf[n] = (char)toupper((unsigned char)*abbr);
        ++n;
        ++abbr;
    }
    buf[n] = '\0';

    if (n == 0) {
        return -1;                  /* 只含空白，等同空串 */
    }

    for (i = 0; i < sizeof(TERM_TABLE) / sizeof(TERM_TABLE[0]); ++i) {
        if (strcmp(TERM_TABLE[i].abbr, buf) == 0) {
            return TERM_TABLE[i].layer;
        }
    }

    return 0;                       /* 未收录 */
}
